/* =====================================================================
   TOKYO-DATA.JS — Tokyo for the neighbourhood map
   ---------------------------------------------------------------------
   Generated once. Boundaries: the 23 special wards and the nearest Tama
   cities (dataofjapan/land), with Saitama, Chiba and Kanagawa drawn
   behind as a quiet backdrop (JapanCityGeoJson) so Tokyo is not floating
   in an ocean on three sides.

   At city scale a plain equirectangular around a local origin is exact
   enough (the error over 50 km is centimetres), so:
       x = (lon - lon0) * cos(lat0),  y = -(lat - lat0)
   scaled into the view grid. TOKYO_PROJECT below is the same maths, for
   the neighbourhood pins.
   ===================================================================== */
const TOKYO_MAP = {"view":{"x":0,"y":0,"w":1000,"h":714.4},"kmPerUnit":0.05045,"lon0":139.745,"lat0":35.67,"cos0":0.81238896,"x0":-0.22340696,"y0":-0.16,"scale":2198.1026};

/* lat/lon -> a point in the TOKYO_MAP.view grid */
function TOKYO_PROJECT(lat, lon) {
  var t = TOKYO_MAP;
  return {
    x: (((lon - t.lon0) * t.cos0) - t.x0) * t.scale,
    y: ((-(lat - t.lat0)) - t.y0) * t.scale
  };
}

